v class="vc_tta-panel-body"><h2 style="text-align: center" class="vc_custom_heading vc_do_custom_heading" >About The Department</h2><div class="vc_row wpb_row vc_inner vc_row-fluid"><div class="wpb_column vc_column_container vc_col-sm-6"><div class="vc_column-inner"><div class="wpb_wrapper">
	<div  class="wpb_single_image wpb_content_element vc_align_left wpb_content_element">
		
		<figure class="wpb_wrapper vc_figure">
			<div class="vc_single_image-wrapper vc_box_border  vc_box_border_grey"><img fetchpriority="high" decoding="async" width="800" height="533" src="../wp-content/uploads/2026/01/departmentoEE.html" class="vc_single_image-img attachment-full" alt="" title="departmentoEE" srcset="assets/images/departmentoEE.jpg 800w, assets/images/departmentoEE-300x200.jpg 300w, assets/images/departmentoEE-768x512.jpg 768w" sizes="(max-width: 800px) 100vw, 800px" /></div>
		</figure>
